#!/usr/bin/env python3
"""results/fp32scan/*.json -> results/fp32scan/FP32SCAN.md"""
import json
import pathlib

R = pathlib.Path(__file__).resolve().parents[2] / "results" / "fp32scan"
J = lambda n: json.load(open(R / n)) if (R / n).exists() else None

allc = J("f32_all.json")
hdr = {h["child"]: h for h in (J("headers.json") or [])}
L = ["# Public fine-tunes stored in fp32: what their weights show", "",
     "Generated by `scripts/fp32scan/report.py`. Wording follows STYLE.md. Each token in a model's vocabulary has its own",
     "vector of numbers (its embedding); a token that never appears in training keeps a vector bit-identical to the base",
     "model. In an fp32 release every change keeps its full precision, so the size and timing of updates can be estimated.",
     "", "## 1. Candidates", "",
     f"Scanned the {6000} most-downloaded and {8000} most-liked text-generation models on Hugging Face (safetensors headers",
     "only). A model qualifies when at least 95% of its parameters are stored as F32 and its card names a base model.",
     f"{len(allc)} models are stored in fp32; {sum(1 for r in allc if r['base'])} name a base model;",
     f"{sum(1 for r in allc if r['base'] and r['datasets'])} also name their training data. The 30 most-liked with a base:", "",
     "| model | likes | downloads | params (B) | base | data named on card | embedding (child / base) |", "|---|---|---|---|---|---|---|"]
for r in sorted([r for r in allc if r["base"]], key=lambda r: -r["likes"])[:30]:
    h = hdr.get(r["repo"])
    emb = "-"
    if h:
        f = lambda e: (list(e.values())[0][0] if isinstance(e, dict) and e else "n/a")
        emb = f"{f(h['child_emb'])} / {f(h['parent_emb'])}" + (" (shared input/output matrix)" if h["child_tie"] is True else "")
    base = r["base"] if isinstance(r["base"], str) else ", ".join(r["base"][:2])
    L.append(f"| {r['repo']} | {r['likes']} | {r['downloads']} | {r['params'] / 1e9:.1f} | {base} | "
             f"{', '.join((r['datasets'] or [])[:2]) or '-'} | {emb} |")

# ---- s1
L += ["", "## 2. s1-32B and s1.1-32B (simplescaling)", "",
      "Base Qwen2.5-32B-Instruct (bf16), release fp32, training data public (s1K / s1K-1.1, 1,000 documents each),",
      "training script public (`train/sft.sh`: 5 epochs, batch 16 on 16 GPUs, cosine, 5% warm-up, peak 1e-5,",
      "Adam betas 0.9/0.95, weight decay 1e-4). The token-set comparison with the published data is reported by the",
      "published-data lane (results/published); here only the parts that need fp32.", ""]
st = J("s1_storage.json") or {}
for m in ("s1-32B", "s1.1-32B"):
    s = st.get(f"simplescaling/{m}")
    t = J(f"{m}.timing.json")
    pd = J(f"{m}.perdoc.json")
    if not (s and t):
        continue
    sc = t["seed_scan"]
    top = sc["top"][0]
    fin = t["final"]
    nxt = next(x for x in sc["top"] if x["seed"] != top["seed"])
    L += [f"### {m}", "",
          f"- **Storage:** {s['changed']:,} token vectors changed, {s['bit_identical']:,} bit-identical to the base. "
          f"{100 * s['changed_values_off_bf16_grid']:.3f}% of the changed numbers are off the 16-bit grid, so the "
          "training kept fp32 master weights and the release carries full precision.",
          f"- **Weight decay:** all {s['bit_identical']:,} never-updated vectors are bit-identical to the base. With "
          "lr x wd <= 1e-9 per step, the per-step factor 1 - lr x wd rounds to exactly 1.0 in fp32, so the published "
          "weight decay of 1e-4 cannot change any number; the weights agree. (No replay or +-1-step control is possible: "
          "there is no decay to replay.)",
          f"- **Shuffle seed and batch size:** {t['rare_tokens']:,} tokens appear in exactly one document. Under the "
          "Hugging Face Trainer convention (epoch e order = torch.randperm(1000) seeded with seed + e), every candidate "
          "(seed, batch size) predicts when each such token was updated, and so how far its vector moved. Of "
          f"{sc['seeds']} seeds x batch sizes {sc['batch_sizes']}, the best fit is **seed {top['seed']}, batch "
          f"{top['bs']}** ({top['N']} steps): median misfit {top['med_dev']:.3f} vs {sc['median_dev']:.3f} for the "
          f"typical seed and {sc['p01_dev']:.3f} at the best 1% of all candidates. The runner-up is seed {nxt['seed']}, "
          "which shares 4 of 5 epoch orders with seed 42 (seed + e). Seed 42 is the Trainer default; the script sets none.",
          f"- **Schedule (seed fixed):** all 8 best fits are cosine (no linear or constant schedule, and no beta2 of "
          f"0.98, 0.99 or 0.999, reaches the top 8); warm-up {fin['W']} steps of {fin['N']} "
          f"(published: 5% = 16) fits best but 13-19 are within noise; Adam beta2 0.95. "
          f"Estimated peak learning rate {fin['peak']:.2e} (published 1e-5): low by "
          f"{100 * (1 - fin['peak'] / 1e-5):.0f}% because the size model assumes equal gradient sizes at each of a "
          "token's five updates.",
          ]
    if pd:
        L.append(f"- **Single documents:** with the seed known, every document's 5 training steps follow from the shuffle. "
                 f"Checked one document at a time (documents with >=3 single-document tokens, n={pd['docs_with_3_rare']}), "
                 f"seed 42's step pattern beats all {pd['other_seeds']} other seeds for {pd['docs_where_seed_beats_all_others']} "
                 f"documents and is in the best 5% for {pd['docs_where_seed_in_top_5pct']} (chance: "
                 f"{0.05 * pd['docs_with_3_rare']:.0f}). The seed is identified from all documents together; individual "
                 "document steps are implied by it, not independently confirmed.")
    L.append("")

# ---- others
L += ["## 3. Other fp32 releases checked", ""]
for f, title in (("deepscaler.json", "DeepScaleR-1.5B-Preview (RL from DeepSeek-R1-Distill-Qwen-1.5B)"),
                 ("userlm8b.json", "UserLM-8b (Microsoft, from Llama-3.1-8B)"),
                 ("marin8b.json", "marin-8b-instruct (from marin-8b-base, both fp32)")):
    d = J(f)
    if not d:
        continue
    b = d["best"]
    sp = d.get("special", [])
    bi = [s["tok"] for s in sp if s["state"] == "bit-identical"]
    L.append(f"- **{title}:** best-matching base `{d['best_parent']}`; {b['bit_identical']:,} token vectors bit-identical, "
             f"{b['changed']:,} changed; single-update ('flat') vectors: {b['flat_vectors']}."
             + (f" Special tokens bit-identical: {len(bi)} of {len(sp)} ({', '.join(bi[:6])}...)." if bi else "")
             + (f" Added vocabulary entries: {b['added_rows']}." if b.get("added_rows") else ""))
L += ["", "- DeepScaleR: the RL updates touched 47,950 vocabulary tokens; the never-updated vectors are bit-identical, so no "
      "weight decay reached them (or lr x wd rounded away in fp32). Every token was updated in many steps, so no timing can be read.",
      "- UserLM-8b and marin-8b-instruct: every token vector changed (UserLM-8b by ~30% relative, marin by ~0.5%), so no token "
      "record survives; both are only 'changed throughout' at the embedding level.", "",
      "## 4. Limits", "",
      "- Step-level timing needs single- or few-update tokens; RL and large SFT runs touch every token many times.",
      "- A release stored as fp32 is not necessarily trained in fp32: check whether its values sit on the 16-bit grid.",
      "- The s1 size model ignores per-update gradient size; it identifies the seed and schedule shape, and estimates the peak "
      "learning rate within ~10%.", ""]
(R / "FP32SCAN.md").write_text("\n".join(L) + "\n")
print("\n".join(L))
